import pandas as pd, numpy as np
r = pd.read_csv('data/ratings.csv.gz', parse_dates=['rated_at'], dtype={'rating_id':str}).sort_values('rating_id').reset_index(drop=True)
lo,hi = pd.Timestamp('2000-04-25'), pd.Timestamp('2000-11-22 23:59:59')
fit = r[(r.rated_at>=lo)&(r.rated_at<=hi)].reset_index(drop=True)
t = pd.Timestamp('2000-11-22')
for mid,rid,exp in [(1333,'R00695198',0.25),(1941,'R00695199',0.3)]:
    sub = fit[(fit.member_id==mid)&(fit.rating_id<rid)]
    hits=[]
    for N in range(2,201):
        if abs(sub.liked.tail(N).mean()-exp)<1e-9: hits.append(('N',N))
    for D in [1,2,3,5,7,10,14,21,28,30,60,90]:
        w = sub[sub.rated_at >= t - pd.Timedelta(days=D)]
        if len(w) and abs(w.liked.mean()-exp)<1e-9: hits.append(('D',D,len(w)))
    print(mid, exp, hits)
